+pub struct RetryPolicy {
+    /// Attempts in total, the first one included.
+    pub max_attempts: u32,
+    /// Delay before the second attempt; doubles per attempt.
+    pub base_delay: Duration,
+    /// Upper bound of one delay, before jitter.
