+impl Default for RetryPolicy {
+    fn default() -> Self {
+        Self { max_attempts: 3, base_delay: Duration::from_millis(200), max_delay: Duration::from_secs(4) }
+    }
+}
+
+impl RetryPolicy {
+    /// True while another attempt is allowed after `attempt` tries.
+    pub fn should_retry(&self, attempt: u32) -> bool {
+        attempt < self.max_attempts
+    }
+
+    /// Delay before the next attempt: exponential, capped, jittered.
+    pub fn backoff(&self, attempt: u32) -> Duration {
+        let raw = exp_delay(self.base_delay, attempt);
+        with_jitter(raw.min(self.max_delay))
+    }
+}
